<?php
session_start(); require_once 'connect.php'; if(isset($_SESSION['user'])){header('Location: dashboard.php');exit;}
$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$password=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';$phone=trim($_POST['phone']??'');
 if($name===''||$username===''||$password===''||$confirm==='') $error='Vui lòng nhập đầy đủ thông tin bắt buộc.';
 elseif(!preg_match('/^[A-Za-z0-9_]{4,50}$/',$username)) $error='Tên đăng nhập 4-50 ký tự, chỉ gồm chữ, số và dấu _. ';
 elseif(strlen($password)<6) $error='Mật khẩu phải có ít nhất 6 ký tự.';
 elseif($password!==$confirm) $error='Mật khẩu xác nhận không khớp.';
 else{$s=$conn->prepare('SELECT id FROM users WHERE username=?');$s->bind_param('s',$username);$s->execute();if($s->get_result()->fetch_assoc())$error='Tên đăng nhập đã tồn tại.';else{$h=password_hash($password,PASSWORD_DEFAULT);$role='tenant';$s=$conn->prepare('INSERT INTO users(username,password,full_name,role) VALUES(?,?,?,?)');$s->bind_param('ssss',$username,$h,$name,$role);if($s->execute()){$uid=$s->insert_id;$t=$conn->prepare('INSERT INTO tenants(user_id,full_name,phone) VALUES(?,?,?)');$t->bind_param('iss',$uid,$name,$phone);$t->execute();$success='Đăng ký tài khoản Người thuê thành công. Chủ trọ sẽ gán phòng/hợp đồng cho bạn.';$_POST=[];}else $error='Không thể đăng ký tài khoản.';}}
}
?>
